  ko: { directionalChaosPursuit: { title: "불규칙 시선 추적 훈련", subtitle: "돌발 표적 · 빠른 시선 재포착", description: "방향과 속도가 바뀌는 표적을 따라가며 시선을 다시 맞추는 브라우저 훈련입니다. 이 페이지는 안구 위치나 임상 결과가 아닌 화면 과제를 기록합니다.", caption: "예측하기 어려운 방향과 속도 변화 뒤에도 움직이는 표적을 다시 찾아 시선을 이어가세요.", status: "상태", tracking: "추적 중", complete: "완료", standby: "대기", timeLeft: "남은 시간", speed: "속도", sessions: "세션", sound: "소리 켜기/끄기", getReady: "준비하세요", setup: "훈련 설정", sessionTime: "세션 시간", targetSpeed: "표적 속도", size: "크기", color: "색상", hideLine: "경로 숨기기", randomSpeed: "무작위 속도", gazeTrail: "시선 흔적", neonGlow: "네온 효과", scanlines: "스캔라인", dayMode: "밝은 화면", start: "훈련 시작", rotateMobile: "더 편하게 하려면 모바일을 가로로 돌리세요", sessionComplete: "세션 완료", calibrated: "반응형 추적 확인", baseSpeed: "기본 속도", sessionsCompleted: "완료한 세션", acceleration: "속도 가속", enabled: "켜짐", fixed: "고정", playAgain: "다시 하기", shareScore: "기록 공유", returnOptions: "설정으로 돌아가기", rules: "훈련 방법과 설정", about: "불규칙 시선 추적 안내", aboutHeading: "이 시선 추적 훈련은 무엇을 하나요?", aboutText: "표적의 방향과 속도를 바꾸어 다음 움직임을 외우는 것보다 실제 시각 피드백에 반응하게 합니다. 눈으로 표적을 따라가고 포인터는 주의 보조로만 사용하세요. 이 화면 과제는 안구 위치를 기록하지 않습니다.", ruleItems: [{ title: "반응형 추적", detail: "실시간 시각 피드백", badge: "표적 재포착" }, { title: "세션 시간", detail: "30~120초", badge: "반복할 시간 선택" }, { title: "경로 표시", detail: "표시 또는 숨김", badge: "예측 부담을 단계적으로 추가" }, { title: "속도 변화", detail: "고정 또는 무작위", badge: "통제하며 진행" }], colorNames: ["사이버 레드", "에메랄드 그린", "네온 블루", "레이저 오렌지", "고시인성 옐로", "순백색"], shareTitle: "불규칙 시선 추적 — 내 세션", shareText: "불규칙 시선 추적 훈련을 {score}배 속도로 완료했어요. 표적을 다시 포착할 수 있나요?" } },
  ja: { directionalChaosPursuit: { title: "動体視力トレーニング", subtitle: "不規則な標的 · 視線の素早い再捕捉", description: "方向と速度が変わる標的を目で追い、見失った後に視線を戻すブラウザ練習です。記録するのは画面上の課題で、眼球位置や診断結果ではありません。", caption: "予測しにくい方向や速度の変化の後も、動く標的を見つけて視線をつなげます。", status: "状態", tracking: "追跡中", complete: "完了", standby: "待機", timeLeft: "残り時間", speed: "速度", sessions: "セッション", sound: "サウンド切替", getReady: "準備してください", setup: "練習設定", sessionTime: "練習時間", targetSpeed: "標的の速度", size: "大きさ", color: "色", hideLine: "軌道を隠す", randomSpeed: "ランダム速度", gazeTrail: "視線の軌跡", neonGlow: "ネオンの光", scanlines: "走査線", dayMode: "明るい画面", start: "練習を開始", rotateMobile: "スマートフォンは横向きにすると操作しやすくなります", sessionComplete: "セッション完了", calibrated: "反応追跡を確認しました", baseSpeed: "基本速度", sessionsCompleted: "完了セッション", acceleration: "速度変化", enabled: "有効", fixed: "固定", playAgain: "もう一度", shareScore: "記録を共有", returnOptions: "設定に戻る", rules: "練習方法と設定", about: "反応型視覚追跡について", aboutHeading: "この動体視力練習では何をしますか？", aboutText: "標的の方向と速度を変えることで、次の動きを記憶するだけでなく実際の視覚フィードバックに反応します。目で標的を追い、ポインターは注意の補助として使います。眼球位置を直接記録する練習ではありません。", ruleItems: [{ title: "反応型の追跡", detail: "リアルタイム視覚フィードバック", badge: "標的を再捕捉" }, { title: "練習時間", detail: "30〜120秒", badge: "繰り返せる長さを選ぶ" }, { title: "軌道の表示", detail: "表示または非表示", badge: "予測の負荷を少しずつ加える" }, { title: "速度の変化", detail: "固定またはランダム", badge: "制御しながら進める" }], colorNames: ["サイバーレッド", "エメラルドグリーン", "ネオンブルー", "レーザーオレンジ", "高視認イエロー", "純白"], shareTitle: "動体視力トレーニング — セッション", shareText: "動体視力トレーニングを{score}倍の速度で完了しました。標的を再捕捉できますか？" } },
