  const howToSchema = { "@context": "https://schema.org", "@type": "HowTo", name: d.introTitle, description: d.description, dateModified: "2026-09-20", step: d.protocols.map((step, i) => ({ "@type": "HowToStep", position: i + 1, name: step.title, text: step.description, url: `${url}#step-${i + 1}` })) };
  return { metadata: { title: `${d.title} | SkillDrills`, description: d.description, keywords: d.keywords, openGraph: { title: `${d.title} | SkillDrills`, description: d.description, type: "article", url, siteName: "SkillDrills", locale: d.locale }, twitter: { card: "summary_large_image", title: `${d.title} | SkillDrills`, description: d.description }, robots: { index: true, follow: true }, alternates: { canonical: url, languages } }, breadcrumbSchema, softwareApplicationSchema, webApplicationSchema, videoGameSchema, faqSchema, howToSchema };
